using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Drawing;
using System.Threading;
using System.Web.Script.Serialization;
namespace PZ3D {
 static class SaveProfiles {
  const int MaxText=1024*1024,MaxCover=512*1024;
  static readonly UTF8Encoding Utf8=new UTF8Encoding(false,true);
  sealed class Document {public byte[] Bytes;public bool Bom;public string Text;public Match Block;public string[] Mods,Maps;}
  internal sealed class Entry {public string id,name,title,author,description,version,source,workshopId,item,cover="",coverToken;public string[] requires,require,loadAfter,loadBefore,conflicts;public Dictionary<string,string> metadata;public bool conflict,map,hasCover,componentManaged;internal string posterRoot,poster;}
  static void Safe(string path){LauncherMaintenance.NoReparse(path);}
  static string[] Dirs(string path,List<string> warnings,LaunchReadBudget budget=null){try{Safe(path);if(!Directory.Exists(path))return new string[0];var dirs=budget==null?Directory.GetDirectories(path):budget.Directories(path);return dirs.Where(p=>{try{Safe(p);return true;}catch{if(budget!=null)budget.Unknown();warnings.Add("已跳过联接或重解析目录。");return false;}}).ToArray();}catch(Exception x){if(budget!=null)budget.Unknown();warnings.Add(x.Message);return new string[0];}}
  static byte[] Bytes(string path,LaunchReadBudget budget=null,int maximum=MaxText){if(budget!=null)return budget.Read(path,maximum);Safe(path);using(var input=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){if(input.Length>maximum)throw new Exception("模组配置超出大小或预检读取预算限制。");var bytes=new byte[(int)input.Length];int offset=0,count;while(offset<bytes.Length&&(count=input.Read(bytes,offset,bytes.Length-offset))>0)offset+=count;if(offset!=bytes.Length)throw new Exception("模组配置读取未完成。");return bytes;}}
  static string Decode(byte[] b,out bool bom){bom=b.Length>=3&&b[0]==239&&b[1]==187&&b[2]==191;string s=Utf8.GetString(b,bom?3:0,b.Length-(bom?3:0));if(s.IndexOf('\0')>=0)throw new Exception("不支持的配置编码。");return s;}
  static Document Parse(byte[] bytes){bool bom;string text=Decode(bytes,out bom);var blocks=Regex.Matches(text,@"(?ms)^\s*mods\s*\{([^{}]*)\}");if(blocks.Count!=1)throw new Exception("配置需包含唯一的 mods 块；未知语法未修改。");var mods=Regex.Matches(blocks[0].Groups[1].Value,@"(?m)^\s*mod\s*=\s*([^,\r\n]+)\s*,\s*$").Cast<Match>().Select(m=>m.Groups[1].Value.Trim()).ToArray();
   var maps=Regex.Matches(text,@"(?ms)^\s*maps\s*\{([^{}]*)\}").Cast<Match>().SelectMany(m=>Regex.Matches(m.Groups[1].Value,@"(?m)^\s*map\s*=\s*(.*?)\s*,\s*$").Cast<Match>().Select(v=>v.Groups[1].Value.Trim())).ToArray();return new Document{Bytes=bytes,Bom=bom,Text=text,Block=blocks[0],Mods=mods,Maps=maps};}
  static string Hash(byte[] b){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(b)).Replace("-","").ToLowerInvariant();}
  public static string ResolveSave(Engine e,string id){if(string.IsNullOrWhiteSpace(id)||id.Length>260||id.Contains('\\')||id.Contains(':'))throw new Exception("无效存档标识。");string[] parts=id.Split('/');if(parts.Length!=2||parts.Any(part=>part.Length==0||part=="."||part==".."||part.EndsWith(".")||part.EndsWith(" ")||part.IndexOfAny(Path.GetInvalidFileNameChars())>=0))throw new Exception("无效存档标识。");string root=Path.GetFullPath(Path.Combine(e.User,"Saves")),p=Path.GetFullPath(Path.Combine(root,parts[0],parts[1]));if(!p.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("存档路径越界。");Safe(p);if(!Directory.Exists(p))throw new Exception("存档不存在，请刷新。");return p;}
  static Document Load(Engine e,string path,out bool inherited){string f=Path.Combine(path,"mods.txt");Safe(f);inherited=!File.Exists(f);return Parse(inherited?(File.Exists(e.Mods)?Bytes(e.Mods):Utf8.GetBytes("VERSION = 1,\nmods\n{\n}\nmaps\n{\n}\n")):Bytes(f));}
  static string Stamp(Document d,bool inherited){return (inherited?"inherited:":"file:")+Hash(d.Bytes);}
public static object Read(Engine e,string id){string path=ResolveSave(e,id);bool inherited;var d=Load(e,path,out inherited);return new{id=id,name=Path.GetFileName(path),mode=id.Split('/')[0],stamp=Stamp(d,inherited),enabled=LaunchProfiles.PersistentMods(e,d.Mods),maps=d.Maps,requiresConfirmation=inherited,warnings=inherited?new[]{"存档缺少 mods.txt，当前显示实际默认模组；确认后才创建存档配置。"}:new string[0]};}
  public static void ValidateForLaunch(Engine e,string id){bool inherited;var d=Load(e,ResolveSave(e,id),out inherited);if(d.Mods.Any(m=>!Id(m))||d.Mods.Distinct(StringComparer.Ordinal).Count()!=d.Mods.Length)throw new Exception("当前存档包含无效或重复模组 ID。");string remaining=Regex.Replace(d.Block.Groups[1].Value,@"(?m)^\s*mod\s*=\s*([^,\r\n]+)\s*,\s*$","");if(!string.IsNullOrWhiteSpace(remaining))throw new Exception("当前存档 mods 块含未知语法，请在游戏内核实。");Validate(d.Mods,Entries(e,new List<string>()));}
  public static object List(Engine e){var warnings=new List<string>();var rows=new List<object>();string root=Path.Combine(e.User,"Saves");foreach(string mode in Dirs(root,warnings))foreach(string path in Dirs(mode,warnings)){string id=Path.GetFileName(mode)+"/"+Path.GetFileName(path);try{bool inherited;var d=Load(e,ResolveSave(e,id),out inherited);rows.Add(new{id=id,name=Path.GetFileName(path),mode=Path.GetFileName(mode),modifiedUtc=Directory.GetLastWriteTimeUtc(path).ToString("o"),modCount=d.Mods.Length,editable=!Path.GetFileName(mode).Equals("Multiplayer",StringComparison.OrdinalIgnoreCase)});}catch(Exception x){warnings.Add(id+"："+x.Message);}}return new{saves=rows,warnings=warnings};}
  internal static bool Id(string s){return !string.IsNullOrWhiteSpace(s)&&s.Length<=200&&!s.Any(c=>char.IsControl(c)||c==','||c==';'||c=='='||c=='{'||c=='}');}
  internal static byte[] DefaultBytes(Engine e){Safe(e.Mods);return File.Exists(e.Mods)?Bytes(e.Mods):null;}
  internal static string[] DefaultMods(byte[] bytes){return Parse(bytes??Utf8.GetBytes("VERSION = 1,\nmods\n{\n}\nmaps\n{\n}\n")).Mods;}
  internal static byte[] ReplaceDefaultMods(byte[] bytes,string[] mods){var d=Parse(bytes??Utf8.GetBytes("VERSION = 1,\nmods\n{\n}\nmaps\n{\n}\n"));string body=d.Block.Groups[1].Value;string remaining=Regex.Replace(body,@"(?m)^\s*mod\s*=\s*([^,\r\n]+)\s*,\s*$","");if(!string.IsNullOrWhiteSpace(remaining))throw new Exception("mods 块含未知语法，未修改。");string nl=d.Text.Contains("\r\n")?"\r\n":"\n";string replacement=nl+string.Concat(mods.Select(m=>"    mod = "+m+","+nl));int start=d.Block.Groups[1].Index;byte[] output=Utf8.GetBytes(d.Text.Substring(0,start)+replacement+d.Text.Substring(start+body.Length));return d.Bom?new byte[]{239,187,191}.Concat(output).ToArray():output;}
  public static object Save(Engine e,string id,string stamp,string[] mods,bool confirmed){e.Guard();string path=ResolveSave(e,id);string name="Local\\OrangeSaveProfiles-"+Hash(Utf8.GetBytes(Path.GetFullPath(Path.Combine(path,"mods.txt")).ToUpperInvariant()));using(var mutex=new Mutex(false,name)){bool held=false;try{try{held=mutex.WaitOne(5000);}catch(AbandonedMutexException){held=true;}if(!held)throw new Exception("存档配置正被其他窗口修改，请稍后重试。");return SaveLocked(e,id,stamp,mods,confirmed,path);}finally{if(held)mutex.ReleaseMutex();}}}
  static object SaveLocked(Engine e,string id,string stamp,string[] mods,bool confirmed,string path){e.Guard();Safe(path);if(id.Split('/')[0].Equals("Multiplayer",StringComparison.OrdinalIgnoreCase))throw new Exception("联机存档只读。");bool inherited;var d=Load(e,path,out inherited);if(Stamp(d,inherited)!=stamp)throw new Exception("配置已被其他程序修改，请刷新。");if(mods!=null)mods=mods.Select(m=>m==null?null:m.Trim()).ToArray();if(mods==null||mods.Length>2000||mods.Any(m=>!Id(m))||mods.Distinct(StringComparer.Ordinal).Count()!=mods.Length)throw new Exception("无效或重复的模组 ID。");mods=LaunchProfiles.PersistentMods(e,mods);if(!confirmed&&(inherited||d.Mods.Except(mods).Any()))throw new Exception("创建独立配置或移除模组需要明确确认。");
   string body=d.Block.Groups[1].Value;string remaining=Regex.Replace(body,@"(?m)^\s*mod\s*=\s*([^,\r\n]+)\s*,\s*$","");if(!string.IsNullOrWhiteSpace(remaining))throw new Exception("mods 块含未知语法，未修改。");Validate(mods,Entries(e,new List<string>()));string nl=d.Text.Contains("\r\n")?"\r\n":"\n";string newBody=nl+string.Concat(mods.Select(m=>"    mod = "+m+","+nl));int start=d.Block.Groups[1].Index;string text=d.Text.Substring(0,start)+newBody+d.Text.Substring(start+body.Length);byte[] output=Utf8.GetBytes(text);if(d.Bom)output=new byte[]{239,187,191}.Concat(output).ToArray();string file=Path.Combine(path,"mods.txt"),temp=file+".orange-"+Guid.NewGuid().ToString("N")+".tmp";try{Safe(temp);File.WriteAllBytes(temp,output);e.Guard();Safe(file);bool nowInherited;var now=Load(e,path,out nowInherited);if(Stamp(now,nowInherited)!=stamp)throw new Exception("配置已被其他程序修改，请刷新。");if(inherited)File.Move(temp,file);else File.Replace(temp,file,null);}finally{if(File.Exists(temp))File.Delete(temp);}return Read(e,id);}
  static void Validate(string[] ids,List<Entry> entries){var lookup=entries.GroupBy(m=>m.id,StringComparer.Ordinal).ToDictionary(g=>g.Key,g=>g.ToArray(),StringComparer.Ordinal);var positions=ids.Select((id,i)=>new{id,i}).ToDictionary(x=>x.id,x=>x.i,StringComparer.Ordinal);foreach(string id in ids){if(!lookup.ContainsKey(id)||lookup[id].Length!=1)throw new Exception("模组缺失或 ID 冲突："+id);foreach(string dep in lookup[id][0].requires){if(!positions.ContainsKey(dep))throw new Exception("缺少依赖："+id+" → "+dep);if(positions[dep]>=positions[id])throw new Exception("依赖顺序或循环错误："+id+" → "+dep);}}}
  internal sealed class CatalogSnapshot {internal List<Entry> Entries;internal object Catalog;}
  internal static void InvalidateDisplay(Engine e){DisplayCache.Invalidate(e);}
  internal static CatalogSnapshot DisplaySnapshot(Engine e){return DisplayCache.Read(e,"catalog",()=>{var w=new List<string>();var entries=Entries(e,w);var managed=new HashSet<string>(ModConfigurations.Managed(entries.Select(entry=>entry.id.TrimStart('\\')).ToArray()),StringComparer.Ordinal);var json=new JavaScriptSerializer{MaxJsonLength=2097152};var rows=new List<Entry>();int size=0;foreach(var entry in entries){entry.componentManaged=managed.Contains(entry.id.TrimStart('\\'));int length=json.Serialize(entry).Length;if(size+length>1400000){w.Add("模组目录超过单次显示限制；部分条目未显示。");break;}rows.Add(entry);size+=length;}return new CatalogSnapshot{Entries=entries,Catalog=new{mods=rows,warnings=w.Select(s=>Bound(s,512)).Distinct(StringComparer.Ordinal).Take(100).ToArray()}};});}
  public static object Catalog(Engine e){return DisplaySnapshot(e).Catalog;}
  static string Bound(string text,int length){return text.Length<=length?text:text.Substring(0,length);}
  public static object Cover(Engine e,string token){if(token==null||!Regex.IsMatch(token,"^[a-f0-9]{64}$"))throw new Exception("无效封面标识。");var matches=DisplaySnapshot(e).Entries.Where(x=>x.coverToken==token).ToArray();if(matches.Length!=1)throw new Exception("封面不存在或标识冲突，请刷新目录。");var entry=matches[0];return new{token=token,cover=ReadCover(entry.posterRoot,entry.poster,new List<string>())};}
  static Dictionary<string,string> Info(string path,LaunchReadBudget budget=null){Safe(path);bool bom;var values=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(string line in Decode(Bytes(path,budget,budget==null?MaxText:262144),out bom).Split('\n')){int eq=line.IndexOf('=');if(eq>0)values[line.Substring(0,eq).Trim()]=line.Substring(eq+1).Trim();}return values;}
  static string Value(Dictionary<string,string> v,string k){string s;return v.TryGetValue(k,out s)?s:"";}
  static Version Current(Engine e,List<string> w){foreach(string relative in new[]{"game-version.txt","version.txt","media/version.txt"}){string path=Path.Combine(e.Game,relative);try{if(File.Exists(path)){bool bom;var m=Regex.Match(Decode(Bytes(path),out bom),@"\b(42\.\d+(?:\.\d+)?)\b");Version v;if(m.Success&&Version.TryParse(m.Value,out v))return v;}}catch{w.Add("游戏版本文件无法安全读取。");}}var probed=GameVersionProbe.Read(e.Game);if(probed!=null&&probed.Major==42)return probed;w.Add("未读取到游戏小版本，使用 B42 通用目录。");return new Version(42,0);}
  internal static List<Entry> Entries(Engine e,List<string> w,bool knownPathsOnly=false,LaunchReadBudget budget=null){Version current=Current(e,w);var result=new List<Entry>();budget=knownPathsOnly?(budget??new LaunchReadBudget(16777216)):null;var roots=new List<string>{e.Workshop};var selectedRoots=new List<string>(new[]{e.BuddySource,e.ViewSource,e.ModelsSource}.Where(s=>!string.IsNullOrEmpty(s)));if(knownPathsOnly){string cache=Path.Combine(e.Data,"workshop-paths.json");Safe(cache);if(File.Exists(cache)){byte[] cacheBytes;try{cacheBytes=Bytes(cache,budget);}catch(LaunchReadBudget.Exhausted){w.Add("工坊来源记录未在累计读取预算内核实；已保留可安全检查的已知目录。");cacheBytes=null;}if(cacheBytes!=null){Dictionary<string,string> paths;try{paths=new JavaScriptSerializer{MaxJsonLength=MaxText,RecursionLimit=8}.Deserialize<Dictionary<string,string>>(Utf8.GetString(cacheBytes));}catch(ArgumentException){throw new Exception("已记录工坊来源数据格式无效，无法完成模组依赖检查。");}catch(InvalidOperationException){throw new Exception("已记录工坊来源数据格式无效，无法完成模组依赖检查。");}if(paths==null||paths.Count>2000||paths.Values.Any(p=>string.IsNullOrWhiteSpace(p)||!Path.IsPathRooted(p)))throw new Exception("已记录工坊来源无效或超出数量限制。");selectedRoots.AddRange(paths.Values);}}}if(!e.TestMode&&!knownPathsOnly){foreach(string steam in GameDiscovery.SteamRoots()){roots.Add(Path.Combine(steam,"steamapps/workshop/content/108600"));string libraries=Path.Combine(steam,"steamapps/libraryfolders.vdf");try{if(File.Exists(libraries)){Safe(libraries);foreach(Match m in Regex.Matches(File.ReadAllText(libraries),"\"path\"\\s*\"([^\"]+)\""))roots.Add(Path.Combine(m.Groups[1].Value.Replace("\\\\","\\"),"steamapps/workshop/content/108600"));}}catch(Exception x){w.Add(x.Message);}}}
   var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(string root in roots.Distinct(StringComparer.OrdinalIgnoreCase))foreach(string item in Dirs(root,w,budget))foreach(string mod in Dirs(Path.Combine(item,"mods"),w,budget))Add(mod,"workshop",Path.GetFileName(item),current,result,w,seen,budget);foreach(string mod in Dirs(Path.Combine(e.User,"mods"),w,budget))Add(mod,"user","",current,result,w,seen,budget);
   foreach(string selected in selectedRoots.Distinct(StringComparer.OrdinalIgnoreCase)){Add(selected,"selected","",current,result,w,seen,budget);foreach(string mod in Dirs(Path.Combine(selected,"mods"),w,budget))Add(mod,"selected","",current,result,w,seen,budget);}
   foreach(var group in result.GroupBy(m=>m.id,StringComparer.Ordinal).Where(g=>g.Count()>1))foreach(var entry in group)entry.conflict=true;return result;}
  static void Add(string root,string source,string workshop,Version current,List<Entry> result,List<string> w,HashSet<string> seen,LaunchReadBudget budget=null){try{Safe(root);if(!Directory.Exists(root)||!seen.Add(Path.GetFullPath(root)))return;var dirs=Dirs(root,w,budget);string common=dirs.FirstOrDefault(d=>Path.GetFileName(d).Equals("common",StringComparison.OrdinalIgnoreCase));var candidates=new List<KeyValuePair<Version,string>>();foreach(string d in dirs){string name=Path.GetFileName(d);Version v;if(name=="42")v=new Version(42,0);else if(!Version.TryParse(name,out v))continue;if(v.Major==42&&v<=current)candidates.Add(new KeyValuePair<Version,string>(v,d));}string active=candidates.OrderByDescending(c=>c.Key).Select(c=>c.Value).FirstOrDefault();if(active==null&&common!=null)return;if(active==null)active=root;
   string info=Path.Combine(active,"mod.info"),commonInfo=common==null?null:Path.Combine(common,"mod.info");var values=commonInfo!=null&&File.Exists(commonInfo)?Info(commonInfo,budget):new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);string posterRoot=common??active;if(File.Exists(info)){var overlay=Info(info,budget);if(overlay.ContainsKey("poster"))posterRoot=active;foreach(var pair in overlay)values[pair.Key]=pair.Value;}else if(values.Count==0)return;string id=Value(values,"id");if(!Id(id)){w.Add("已跳过无效 mod.info ID。");return;}string[] requires=Edges(values,"require");string poster=Value(values,"poster"),title=Bound(Value(values,"name")==""?id:Value(values,"name"),200);var original=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(var pair in values.Take(64))original[Bound(pair.Key,100)]=Bound(pair.Value,256);if(values.Count>64||values.Any(p=>p.Key.Length>100||p.Value.Length>256))w.Add("作者元数据超过显示限制；目录保留有界原文摘要。");result.Add(new Entry{id=id,name=title,title=title,author=Bound(Value(values,"author"),200),description=Bound(Value(values,"description"),512),version=Bound(Value(values,"modversion")==""?Value(values,"version"):Value(values,"modversion"),100),source=source,workshopId=workshop,item=workshop,posterRoot=posterRoot,poster=poster,hasCover=PosterPath(posterRoot,poster,w)!=null,coverToken=Hash(Utf8.GetBytes(Path.GetFullPath(root).ToUpperInvariant()+"\n"+id+"\n"+active.ToUpperInvariant()+"\n"+source)),requires=requires,require=requires,loadAfter=Edges(values,"loadAfter","loadModAfter"),loadBefore=Edges(values,"loadBefore","loadModBefore"),conflicts=Edges(values,"conflicts"),metadata=original,conflict=false,map=Directory.Exists(Path.Combine(active,"media/maps"))||(common!=null&&Directory.Exists(Path.Combine(common,"media/maps")))});}catch(Exception x){w.Add("模组目录已跳过："+x.Message);}}
  static string[] Edges(Dictionary<string,string> values,params string[] keys){return keys.SelectMany(key=>Value(values,key).Split(new[]{',',';'},StringSplitOptions.RemoveEmptyEntries)).Select(s=>s.Trim().TrimStart('\\')).Where(s=>s.Length>0).Distinct(StringComparer.Ordinal).ToArray();}
  static string PosterPath(string root,string poster,List<string> w){if(poster=="")return null;try{if(Path.IsPathRooted(poster)||poster.IndexOfAny(new[]{'\\','/',':'})>=0||poster=="..")throw new Exception("封面路径无效。");string p=Path.Combine(root,poster);Safe(p);if(!File.Exists(p)){Version layout;if(Path.GetFileName(root)=="42"||Version.TryParse(Path.GetFileName(root),out layout)){p=Path.Combine(Path.GetDirectoryName(root),"common",poster);Safe(p);}if(!File.Exists(p))return null;}return p;}catch(Exception x){w.Add(x.Message);return null;}}
  static string ReadCover(string root,string poster,List<string> w){try{string p=PosterPath(root,poster,w);if(p==null)return "";long size=new FileInfo(p).Length;if(size==0||size>MaxCover)throw new Exception("封面超出大小限制。");byte[] b=File.ReadAllBytes(p);if(b.Length>MaxCover)throw new Exception("封面超出大小限制。");string mime;if(b.Length>=8&&b.Take(8).SequenceEqual(new byte[]{137,80,78,71,13,10,26,10}))mime="image/png";else if(b.Length>=3&&b[0]==255&&b[1]==216&&b[2]==255)mime="image/jpeg";else throw new Exception("封面格式无效。");using(var stream=new MemoryStream(b))using(var image=Image.FromStream(stream,false,true)){if(image.Width>4096||image.Height>4096)throw new Exception("封面尺寸过大。");}return "data:"+mime+";base64,"+Convert.ToBase64String(b);}catch(Exception x){w.Add(x.Message);return "";}}
 }
}
